#!/usr/bin/env python3
"""Publish compact scientific evidence of real directed diagram connection checks.

Read frozen original TopoBench 69 actual image OCR/Hough and external source
annotated edge evaluations from /data/var. Do not serialize original images,
source link-only images, per-OCR text, source graph details or raw location
predictions into Git. Reconcile source SHA, denominators, user-facing verdict,
engine resources and paired-by-diagram confidence intervals. Source labels are
external curated graph annotations, not human-blind final image certification.
"""
from pathlib import Path
import json,hashlib,collections,statistics
from scipy.stats import binomtest
ROOT=Path('/data/var/perceptual-independent-20261024/topobench-independent-20261025')
REPO=Path(__file__).resolve().parents[2]/'docs/research'
SOURCE=ROOT/'official_topobench_162_test_original.parquet'
PIX=ROOT/'original_69_raster_OCR_line_geometry_frozen_20261025.json'
ANNOT=ROOT/'69_real_diagram_source_annotated_directed_edge_recovery_20261025.json'
OUT=REPO/'perceptual-topobench-69-original-diagram-connector-evidence-2026-10-25.json'
DOC=REPO/'perceptual-topobench-real-directed-connector-research-2026-10-25.md'

def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()

def main():
 if OUT.exists() or DOC.exists():print('ORIGINAL_SOURCE_DECISION_ARTIFACT_ALREADY_PRESERVED_NO_REWRITE');return
 pix=json.loads(PIX.read_text());d=json.loads(ANNOT.read_text())
 assert pix['status']=='complete' and len(pix['source_original_69_results'])==69
 assert pix['source_parquet_sha256']==digest(SOURCE)
 assert d['original_parquet_sha256']==digest(SOURCE)
 assert d['image_only_frozen_features_sha256']==digest(PIX)
 assert d['source_annotation_counts']=={'full_test_source_entries':162,'source_images_redistributed':69,'link_only_excluded':93,'domains':{'ai2d_web':54,'network':15},'source_license_statuses':{'CC BY-SA':54,'CC BY-SA 4.0':2,'CC BY-SA 3.0':1,'Public domain':2,'CC BY 4.0':10}}
 results={}
 for psm in ('11','6'):
  run=d['PSM_image_only_methods'][psm];stats=run['metrics'];rows=[r for x in run['per_source_paired_prediction_labels'].values() for r in x['pairs']]
  directed=[r for r in rows if r['has_unambiguous_directed_truth']]
  aligned=[r for r in directed if r['Hough_flag']]
  correct=sum(r['Hough_layout_direction_guess_is_correct'] is True for r in aligned)
  ambiguous={key:sum(x.get('status')!= 'complete' for x in run['per_source_paired_prediction_labels'].values()) for key in ['diagram_OCR_anchors_incomplete_or_ambiguous_count']}
  btest=binomtest(correct,len(aligned),.5) if aligned else None
  actual={'original_diagrams_with_redistributable_pixels':69,'total_original_annotated_source_nodes':stats['total_original_nodes'],'unique_ocr_grounded_source_nodes':stats['unique_OCR_grounded_nodes'],'source_annotated_undirected_connections_all_diagrams':stats['total_annotated_undirected_links'],'scorable_annotated_connections_both_node_labels_found':stats['source_positive_links_both_grounded'],'unscorable_source_connections_due_ambiguous_or_missing_OCR_anchor':stats['total_unscorable_links_due_unrecognized_nodes'],'actual_annotated_negative_nonconnection_controls_scored':stats['source_negative_links_both_grounded'],'source_diagrams_with_at_least_one_grounded_pair':stats['same_source_diagram_CI']['source_diagrams'],'source_diagram_bootstrap95':stats['same_source_diagram_CI'],'source_conditional_hough_binary':stats['hough_geometry'],'source_conditional_layout_nearest_neighbor_null':stats['source_assisted_OCR_label_nearest_neighbor'],'source_conditional_always_no_connection_null':stats['no_link_baseline'],'source_line_score_ROC_AUC':stats['Hough_score_AUROC'],'source_domains':stats['by_source_domain'],'layout_reading_order_guessed_arrow_orientation_NOT_measured_vision':{'source_unambiguous_directed_node_pairs':len(directed),'hough_detected_unambiguous_directed_connections':len(aligned),'direction_right_under_layout_bias':correct,'direction_wrong_under_layout_bias':len(aligned)-correct,'direction_accuracy_given_detected_directed_edge':correct/len(aligned) if aligned else None,'two_sided_binomial_p_vs_half':float(btest.pvalue) if btest else None,'exact_binomial_95pct_accuracy_CI':[round(btest.proportion_ci(confidence_level=.95,method='exact').low,4),round(btest.proportion_ci(confidence_level=.95,method='exact').high,4)] if btest else None,'this_is_NOT_arrowhead_analysis':True},'diagram_ocr_grounding_abstentions':ambiguous}
  assert stats['total_original_nodes']==740 and stats['total_annotated_undirected_links']==966
  assert actual['scorable_annotated_connections_both_node_labels_found']+actual['unscorable_source_connections_due_ambiguous_or_missing_OCR_anchor']==966
  results[psm]=actual
  print('ORIGINAL_TOPOBENCH_REPRODUCIBLE_SOURCE_PSM',psm,'SCORED_POS',actual['scorable_annotated_connections_both_node_labels_found'],'REAL_NONEDGES',actual['actual_annotated_negative_nonconnection_controls_scored'],'TOTAL_OCR_GROUNDED_NODES',actual['unique_ocr_grounded_source_nodes'],'DIRECTION_RIGHT',correct,'OF',len(aligned),'DIRECTION_PROB_CHANCE',actual['layout_reading_order_guessed_arrow_orientation_NOT_measured_vision']['two_sided_binomial_p_vs_half'])
 a=results['11'];b=results['6'];x=a['source_conditional_hough_binary'];y=a['source_conditional_layout_nearest_neighbor_null']
 assert (x['TP'],x['FP'],x['FN'],x['TN'])==(151,158,47,313)
 assert (y['TP'],y['FP'],y['FN'],y['TN'])==(93,55,105,416)
 assert a['unique_ocr_grounded_source_nodes']==229 and b['unique_ocr_grounded_source_nodes']==173
 assert a['source_diagrams_with_at_least_one_grounded_pair']==38 and b['source_diagrams_with_at_least_one_grounded_pair']==31
 assert a['layout_reading_order_guessed_arrow_orientation_NOT_measured_vision']['direction_right_under_layout_bias']==80
 assert b['layout_reading_order_guessed_arrow_orientation_NOT_measured_vision']['direction_right_under_layout_bias']==44
 doc={'date':'2026-10-25','status':'PARTIAL: line-based source-assisted connection retrieval shows bounded positive conditional signal, far too many false positive source non-edges, low OCR source grounding and no reliable arrow direction','source':'TopoBench-180 external curated original test-only source graphs and sixty-nine legally redistributed real diagram images (fifty-four AI2D and fifteen natural network diagrams), 93 link-only original sources omitted for licensing','upstream':'https://huggingface.co/datasets/WayneGuo0011/TopoBench-180','source_revision':'df366de6a2c8aaf83c0a95ba8bfb1a28e231cb14','source_license_attribution':'AI2D Creative Commons BY-SA plus original individual per-image network licenses; no original pixels, raw OCR or source images added to project Git','original_copyright_redistribution_risk_93_images_not_requested':True,'source_SHA256':{'original_162_test_parquet_including_69_original_images':digest(SOURCE),'original_all69_OCR_plus_Canny_Hough_pixel_predictions':digest(PIX),'original_external_graph_truth_join_score':digest(ANNOT)},'source_image_only_feature_config':pix['config'],'predeclared_frozen_source_annotated_scoring_config':d['config'],'original_pixel_ocr_elapsed_seconds':pix['this_iteration_seconds'],'original_pixel_ocr_peak_RSS_kibibytes':pix['peak_RSS_KB'],'original_GPU_used':False,'source_graph_ground_truth_caveat':'External curated node-centric graph annotations are assumed complete for scoring annotated edge/nonedge relations but do not constitute independently blinded human proof of every pixel or arrow. The OCR image-only extractor did NOT receive these source labels; node grounding after OCR uses expected name references.','PSM_both_predeclared_settings':results,'immediately_usable_recommendation':'If diagram has trusted source graph names, use source graph to validate required nodes and arrow direction logically. Use OCR/Hough line geometry only to suggest image link locations, recording ungrounded nodes/links as unknown, and never auto approve arrow direction or a complete diagram from these methods. For actual final render require explicit visual arrowhead evidence or independent human/specialist review.','limitations':['Source denominator: 69 original diagrams, 740 annotated nodes, 966 source unordered links, BUT only 38 diagrams with grounded endpoint pairs and 198 source links scorable with OCR PSM11; estimates conditioned on successful OCR cannot be treated as full dataset recall.','Hough line alignment is not an arrowhead detector and cannot infer edge direction. A simple reading-order shortcut guessing arrow direction attained only about half accuracy on grounded directed edges.','Source curated topology annotations can omit or contain mistakes in final diagram pixels; apparent false positives may include visually drawn edges not covered by source ground graph.','Original 15 network diagrams differed strongly from 54 AI2D diagrams in OCR grounding; benchmark mixed styles and human annotator source validity needs caution.','Nested diagram annotations and source names are used to match already frozen OCR text bounding boxes, not supplied to image model directly; results are source-assisted, not end-to-end visual parser.','The AUC +0.05 to +0.16 over a nearest-neighbor binary-layout baseline is a source-diagram cluster descriptive interval on an externally curated TEST-only dataset, not post-selection final super-holdout performance.','Some subject/relationship edge direction source truth may be semantically reciprocal and not visually annotated with standalone arrowheads; a line segment can show a connection without a unique direction.','No extra model inference needed; current Nitro RTX3060 production and CPU load protected.']}
 OUT.write_text(json.dumps(doc,indent=2)+'\n')
 report=f'''# Independent real diagram connector detection and direction — new TopoBench source test

**25 October 2026. Owning project: SWAAG visual perception research. Status: PARTIAL.** The original owner question asks which analyzers can correctly judge *actual* diagram images, including arrows and missing/incorrect connections. Earlier SADU research found source graph count checks can be internally consistent while source-linked image OCR finds under half of intended labels; even the best archived VLM had about seventy-two percent exact structural QA accuracy. This distinct continuation uses the external [TopoBench-180 curated topology benchmark](https://huggingface.co/datasets/WayneGuo0011/TopoBench-180), pinned at the original repository revision in the accompanying evidence JSON, with **sixty-nine actual redistributable real diagrams** and their separately released source node/edge annotations. The original test archive has one hundred and sixty-two entries but ninety-three image files are *link-only* and have unresolved redistribution permission; they were **not** retrieved or scored. The sixty-nine originals comprise fifty-four AI2D drawings and fifteen source-licensed network diagrams. Original source pixels, model outputs and external annotations remain under isolated `/data/var`, not in Git. The external graph labels are curated source annotations and not a new independent blinded human re-annotation.

## Before looking at the source graph relationships: true image-only extraction

On the actual image pixels only, predeclared CPU Tesseract **PSM eleven and PSM six**, and Canny plus Hough line segments, were extracted for **all sixty-nine images**, with no source graph names or directed edges passed to the extraction stage. The run was pinned to its dataset revision and actual source parquet hash. The first extractor took about **{round(pix['this_iteration_seconds'])} seconds** wall time on busy Nitro with one low-priority CPU thread and about **{round(pix['peak_RSS_KB']/1024)} MiB** peak RSS; no GPU or model inference. The outputs were frozen before connecting to original source graph labels. Matching a trusted source node name to a uniquely recognized OCR token sequence was permitted only in the later source-assisted scoring step; multiple or missing OCR matches **abstain**. Then a fixed pixel-line alignment score was compared to each expected annotated connection or source-annotated non-edge between uniquely grounded node pairs. A nearest-neighbor layout-only detector, and a trivial no-link policy, were predeclared controls, not tuned after labels.

## External-source true connections versus annotated non-connections

The external images contain **seven hundred and forty source-annotated nodes** and **nine hundred and sixty-six unique undirected connection pairs** (direction handled separately). OCR PSM eleven uniquely grounded just **two hundred and twenty-nine nodes**, with only **thirty-eight of sixty-nine diagrams** providing any scorable grounded node pairs. That left only **one hundred and ninety-eight of nine hundred and sixty-six original annotated connections** with both endpoints located. The other source links are UNKNOWN due to absent or ambiguous OCR grounding, not confirmed no-edges.

Among the **six hundred and sixty-nine conditional node pairs actually scorable** (one hundred and ninety-eight reference edges and four hundred and seventy-one source-negative non-edges), the fixed real image line detector achieved **one hundred and fifty-one true positives, one hundred and fifty-eight false positives, forty-seven false negatives and three hundred and thirteen true negatives**. Recall **{100*x['recall']:.1f} percent**, specificity **{100*x['specificity']:.1f} percent**, precision only **{100*x['precision']:.1f} percent** and balanced accuracy **{100*x['balanced_accuracy']:.1f} percent**. Its continuous line-alignment score ranked annotated edges above non-edges with ROC area **{a['source_line_score_ROC_AUC']:.3f}**, with **ninety-five percent source-diagram clustered bootstrap interval {a['source_diagram_bootstrap95']['CI95']['Hough_AUROC']}**. These are conditional on successfully located nodes and source annotation completeness, **not end-to-end diagram acceptance reliability**.

The same-budget spatial nearest-neighbor baseline achieved **ninety-three true positives, fifty-five false positives, one hundred and five misses and four hundred and sixteen correct negatives** on those exact pairs, or **{100*y['balanced_accuracy']:.1f} percent** balanced accuracy. Thus the line-pixel evidence adds a useful ranking signal: the diagram-grouped bootstrap interval for line-score AUROC minus nearest-neighbor spatial score is **{a['source_diagram_bootstrap95']['CI95']['Hough_AUROC_minus_layout_nearest_AUROC']}**. But this is not accurate enough to reject a diagram automatically, because nearly half the detected connection proposals are false according to source references, and most original links were never OCR grounded. The unconditional always-no-edge baseline has **zero false positives but misses every original connection**, illustrating why specificity alone can be misleading. The independent PSM six setting grounded **one hundred and seventy-three nodes** and found **one hundred and two of one hundred and forty scorable source edges** but falsely flagged **one hundred and twenty-four of three hundred and thirty-four annotated nonedges**; it was not silently selected or pooled with PSM eleven.

## Arrow directions remain genuinely unresolved

A Hough line has no intrinsic arrow direction. To explicitly avoid presenting undirected line hits as correct directed topology, the experimental scorer reported a *direction-of-reading bias-only baseline*: if the image connector proposal exists, guess the arrow points from left to right or top to bottom, **without any arrowhead evidence**. On detected source pairs with exactly one annotated direction, this guessed the source orientation correctly **eighty of one hundred and forty-seven** times with PSM eleven (approximately fifty-four percent), and forty-four of one hundred with PSM six. The primary direction result is consistent with chance. The scorer does not silently count reciprocal source arrows as a single directed edge. The correct practical default is to verify directed edges from authoritative source graph/data, and require visible arrowhead/connector inspection independently when image direction could differ. OCR/Hough is a candidate locator, not a pixel-to-directed-graph model.

## Scope and operating decision

This is one **genuinely new public dataset** with unmodified original diagrams, original source graph positive and negative pairs, a source-blind pixel first stage, two predefined OCR variants and a same-budget layout-only baseline. The original dataset's graph annotations, although curated and useful reference truth, are not independently certified to cover every visible arrow and connector; original source license status is recorded for each category in the local manifest. The deliberately different AI2D and network diagram families make the OCR coverage gap significant. All links whose labels cannot be grounded remain **UNKNOWN**, not passes. An actual source-aware diagram verifier can enforce the required directed source graph and ask the image analysis to propose potential visible connections, but it must not issue a final automatic pass without verified rendered arrowhead direction and text/connector visibility. This does not invalidate existing GUI geometry and axe-core narrow checks, the owner's verified warehouse geometry chain, the source-based video time checks or the prior negative vision model findings. It refines the recommendation: **diagram pixel-line geometry is useful for finding potential connections, while direction, graph completeness and final visual semantics need a stronger oracle**.

**Most decisive remaining technical gap:** independently human-verified drawn arrowhead orientation and absence-of-unwanted-connectors across new diagram types, plus production GUI truly clean controls, unrelated physically certified industrial scenes/renderings and time-coded natural video faults. No production services, GPU models, source files, calendar events, earlier denied results or uncertain Calendar sends were touched. General visual approval remains PARTIAL.
'''
 DOC.write_text(report)
 print('TOPOBENCH_REAL_DIAGRAM_REPORT_PUBLISHED',OUT.stat().st_size,'JSON',DOC.stat().st_size,'MARKDOWN','SOURCE_LABEL_TRUE_RELATION_AMBIGUOUS_CAVEAT',True,'NO_MEDIA_COMMITTED',True)
if __name__=='__main__':main()
